#include <vector>

struct Record {
  Record(const Record&) noexcept(false);
  Record(Record&&) noexcept(false);
};

// Record — Cpp17CopyInsertable для out.
// value — отдельный объект, не элемент out.
void Append(std::vector<Record>& out,
            const Record& value) {
  out.push_back(value);
